import * as React from "react";
import { DropdownMenu as DropdownMenuPrimitive } from "radix-ui";

import { useV4PortalContainer } from "../scope";

import { cn } from "../lib/utils";
import { Icon } from "./icon";
import { menuRowContent, menuShortcutContent } from "./menu-content";

import controlStyles from "./controls.module.css";
import menu from "./menu.module.css";

function DropdownMenu({ ...props }: React.ComponentProps<typeof DropdownMenuPrimitive.Root>) {
  return <DropdownMenuPrimitive.Root data-slot="dropdown-menu" {...props} />;
}

function DropdownMenuPortal({
  ...props
}: React.ComponentProps<typeof DropdownMenuPrimitive.Portal>) {
  return (
    <DropdownMenuPrimitive.Portal
      container={useV4PortalContainer()}
      data-slot="dropdown-menu-portal"
      {...props}
    />
  );
}

const DropdownMenuTrigger = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Trigger>
>(({ className, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Trigger
      ref={ref}
      data-slot="dropdown-menu-trigger"
      className={cn(controlStyles.insetHover, className)}
      {...props}
    />
  );
});
DropdownMenuTrigger.displayName = "DropdownMenuTrigger";

const DropdownMenuContent = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Content>
>(({ className, collisionPadding = 8, align = "start", sideOffset = 4, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Portal container={useV4PortalContainer()}>
      <DropdownMenuPrimitive.Content
        ref={ref}
        data-slot="dropdown-menu-content"
        collisionPadding={collisionPadding}
        sideOffset={sideOffset}
        align={align}
        className={cn("z-50", menu.surface, menu.panel, menu.inset, menu.motion, className)}
        {...props}
      />
    </DropdownMenuPrimitive.Portal>
  );
});
DropdownMenuContent.displayName = "DropdownMenuContent";

const DropdownMenuGroup = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Group>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Group>
>(({ ...props }, ref) => {
  return <DropdownMenuPrimitive.Group ref={ref} data-slot="dropdown-menu-group" {...props} />;
});
DropdownMenuGroup.displayName = "DropdownMenuGroup";

const DropdownMenuItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Item>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Item> & {
    inset?: boolean;
    variant?: "default" | "destructive";
  }
>(({ className, inset, variant = "default", children, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Item
      ref={ref}
      data-slot="dropdown-menu-item"
      data-inset={inset}
      data-variant={variant}
      className={cn(menu.row, className)}
      {...props}
    >
      {menuRowContent(children)}
    </DropdownMenuPrimitive.Item>
  );
});
DropdownMenuItem.displayName = "DropdownMenuItem";

const DropdownMenuCheckboxItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.CheckboxItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.CheckboxItem> & {
    closeOnSelect?: boolean;
  } & {
    inset?: boolean;
  }
>(({ className, children, checked, inset, onSelect, closeOnSelect = false, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.CheckboxItem
      ref={ref}
      data-slot="dropdown-menu-checkbox-item"
      data-inset={inset}
      className={cn(menu.row, className)}
      checked={checked}
      {...props}
      onSelect={(event) => {
        onSelect?.(event);
        if (!closeOnSelect) event.preventDefault();
      }}
    >
      <span className={menu.indicator} data-slot="dropdown-menu-checkbox-item-indicator">
        <DropdownMenuPrimitive.ItemIndicator>
          <Icon name="check" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {menuRowContent(children)}
    </DropdownMenuPrimitive.CheckboxItem>
  );
});
DropdownMenuCheckboxItem.displayName = "DropdownMenuCheckboxItem";

const DropdownMenuRadioGroup = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.RadioGroup>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioGroup>
>(({ ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.RadioGroup ref={ref} data-slot="dropdown-menu-radio-group" {...props} />
  );
});
DropdownMenuRadioGroup.displayName = "DropdownMenuRadioGroup";

const DropdownMenuRadioItem = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.RadioItem>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.RadioItem> & {
    closeOnSelect?: boolean;
  } & {
    inset?: boolean;
  }
>(({ className, children, inset, onSelect, closeOnSelect = false, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.RadioItem
      ref={ref}
      data-slot="dropdown-menu-radio-item"
      data-inset={inset}
      className={cn(menu.row, className)}
      {...props}
      onSelect={(event) => {
        onSelect?.(event);
        if (!closeOnSelect) event.preventDefault();
      }}
    >
      <span className={menu.indicator} data-slot="dropdown-menu-radio-item-indicator">
        <DropdownMenuPrimitive.ItemIndicator>
          <Icon name="check" />
        </DropdownMenuPrimitive.ItemIndicator>
      </span>
      {menuRowContent(children)}
    </DropdownMenuPrimitive.RadioItem>
  );
});
DropdownMenuRadioItem.displayName = "DropdownMenuRadioItem";

const DropdownMenuLabel = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Label>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Label> & {
    inset?: boolean;
  }
>(({ className, inset, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Label
      ref={ref}
      data-slot="dropdown-menu-label"
      data-inset={inset}
      className={cn(menu.label, className)}
      {...props}
    />
  );
});
DropdownMenuLabel.displayName = "DropdownMenuLabel";

const DropdownMenuSeparator = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.Separator>
>(({ className, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.Separator
      ref={ref}
      data-slot="dropdown-menu-separator"
      className={cn(menu.separator, className)}
      {...props}
    />
  );
});
DropdownMenuSeparator.displayName = "DropdownMenuSeparator";

const DropdownMenuShortcut = React.forwardRef<
  React.ComponentRef<"span">,
  React.ComponentPropsWithoutRef<"span">
>(({ className, children, ...props }, ref) => {
  return (
    <span
      ref={ref}
      data-slot="dropdown-menu-shortcut"
      className={cn(menu.shortcut, className)}
      {...props}
    >
      {menuShortcutContent(children)}
    </span>
  );
});
DropdownMenuShortcut.displayName = "DropdownMenuShortcut";

function DropdownMenuSub({ ...props }: React.ComponentProps<typeof DropdownMenuPrimitive.Sub>) {
  return <DropdownMenuPrimitive.Sub data-slot="dropdown-menu-sub" {...props} />;
}

const DropdownMenuSubTrigger = React.forwardRef<
  React.ElementRef<typeof DropdownMenuPrimitive.SubTrigger>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubTrigger> & {
    inset?: boolean;
  }
>(({ className, inset, children, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.SubTrigger
      ref={ref}
      data-slot="dropdown-menu-sub-trigger"
      data-inset={inset}
      className={cn(menu.row, className)}
      {...props}
    >
      {menuRowContent(children)}
      <Icon name="chev-right" className={menu.trail} />
    </DropdownMenuPrimitive.SubTrigger>
  );
});
DropdownMenuSubTrigger.displayName = "DropdownMenuSubTrigger";

const DropdownMenuSubContent = React.forwardRef<
  React.ComponentRef<typeof DropdownMenuPrimitive.SubContent>,
  React.ComponentPropsWithoutRef<typeof DropdownMenuPrimitive.SubContent>
>(({ className, collisionPadding = 8, ...props }, ref) => {
  return (
    <DropdownMenuPrimitive.SubContent
      ref={ref}
      data-slot="dropdown-menu-sub-content"
      collisionPadding={collisionPadding}
      className={cn("z-50", menu.surface, menu.panel, menu.sub, menu.inset, menu.motion, className)}
      {...props}
    />
  );
});
DropdownMenuSubContent.displayName = "DropdownMenuSubContent";

export {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuPortal,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuSub,
  DropdownMenuSubContent,
  DropdownMenuSubTrigger,
  DropdownMenuTrigger
};

.field {
  --v4-field-height: var(--v4-size-control-sm);
  --v4-field-inline: var(--v4-space-control-inline-sm);
  --v4-field-nested: var(--v4-size-nested-sm);
  box-sizing: border-box;
  min-height: var(--v4-field-height);
  padding-block: calc(
    (var(--v4-field-height) - var(--v4-type-body-line-height)) / 2 - var(--v4-size-control-border)
  );
  padding-inline: var(--v4-field-inline);
  border: var(--v4-size-control-border) solid var(--v4-control);
  border-radius: calc(var(--v4-radius-control) * var(--corners));
  background-color: var(--v4-control-surface);
  color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
  transition-property: border-color, box-shadow, background-color;
  transition-duration: var(--v4-duration-fast);
  transition-timing-function: var(--v4-ease-fade);
}
.field[data-size="md"] {
  --v4-field-height: var(--v4-size-control-md);
  --v4-field-inline: var(--v4-space-control-inline-md);
  --v4-field-nested: var(--v4-size-nested-md);
}
.field[data-size="lg"] {
  --v4-field-height: var(--v4-size-control-lg);
  --v4-field-inline: var(--v4-space-control-inline);
  --v4-field-nested: var(--v4-size-nested-lg);
}
.field::placeholder,
.field ::placeholder {
  color: var(--v4-muted);
}
@media (hover: hover) {
  .field:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-control-surface-hover);
  }
}
.field:is(:focus-visible, [aria-expanded="true"]),
.field:has([data-field-control]:focus-visible, .field:is(:focus-visible, [aria-expanded="true"])) {
  border-color: var(--v4-ink);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-focus-ring);
}
.field:is([aria-invalid="true"], [data-invalid]),
.field:has(:is([data-field-control], .field)[aria-invalid="true"]) {
  border-color: var(--v4-control-invalid-border);
}
.field:is([aria-invalid="true"], [data-invalid]):is(:focus-visible, [aria-expanded="true"]),
.field:is([aria-invalid="true"], [data-invalid]):has([data-field-control]:focus-visible),
.field:has(
    [data-field-control][aria-invalid="true"]:focus-visible,
    .field[aria-invalid="true"]:is(:focus-visible, [aria-expanded="true"])
  ) {
  border-color: var(--v4-bad);
  box-shadow: 0 0 0 var(--v4-size-focus-ring) var(--v4-focus-ring-bad);
}
.field:is(:disabled, [aria-disabled="true"]),
.field:has([data-field-control]:disabled) {
  cursor: not-allowed;
  opacity: 0.5;
}
.field:is([readonly], :has([data-field-control][readonly])) {
  background-color: var(--v4-paper);
}
.fieldBox {
  display: flex;
  width: 100%;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-control-gap);
  padding-block: 0;
  cursor: text;
}
.fieldBox:has(> .trailing) {
  padding-inline-end: var(--v4-space-control-slot-inset);
}
.bare {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  min-height: calc(var(--v4-field-height) - 2 * var(--v4-size-control-border));
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  color: inherit;
  font: inherit;
  letter-spacing: inherit;
  outline: none;
}
.bare:disabled {
  cursor: not-allowed;
}
.mono {
  font-family: var(--v4-font-mono, monospace);
}
.leading,
.chevron {
  display: inline-flex;
  flex: none;
  color: var(--v4-muted);
  pointer-events: none;
}
.chevron {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.trigger {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  gap: var(--v4-space-control-gap);
  text-align: start;
  white-space: nowrap;
  cursor: pointer;
}
.insetHover {
  --v4-inset-hover-gap: calc(var(--v4-space-2) + var(--v4-size-control-border));
  --v4-inset-hover-rest: var(--v4-control-surface);
  background-repeat: no-repeat;
  background-position: center;
  background-size: calc(100% - 2 * var(--v4-inset-hover-gap))
    calc(100% - 2 * var(--v4-inset-hover-gap));
}
.insetHover:is([data-variant="outline"], [data-variant="secondary"]) {
  --v4-inset-hover-rest: var(--v4-action-outline-surface);
}
@media (hover: hover) {
  .insetHover:hover:not(:disabled, [aria-disabled="true"]) {
    background-color: var(--v4-inset-hover-rest);
    background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
  }
}
.insetHover[aria-expanded="true"] {
  background-color: var(--v4-inset-hover-rest);
  background-image: linear-gradient(var(--v4-action-ghost-hover), var(--v4-action-ghost-hover));
}
.trigger > :first-child {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.trigger [data-placeholder],
.trigger[data-placeholder] > :first-child {
  color: var(--v4-muted);
}
.textarea {
  min-height: calc(2 * var(--v4-space-32));
  field-sizing: content;
  resize: vertical;
}
.searchRow {
  display: flex;
  min-height: var(--v4-size-control-lg);
  align-items: center;
  gap: var(--v4-space-8);
  padding-inline: calc(var(--v4-space-menu-inset) + var(--v4-space-8));
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
  cursor: text;
}
.searchRow:focus-within {
  color: var(--v4-ink);
}
.searchRow > svg {
  flex: none;
  pointer-events: none;
}
.searchRow > input {
  flex: 1 1 auto;
  align-self: stretch;
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--v4-ink);
  caret-color: var(--v4-ink);
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  outline: none;
}
.searchRow > input::placeholder {
  color: var(--v4-muted);
}
.searchTrailing {
  display: inline-flex;
  flex: none;
  align-items: center;
  color: var(--v4-muted);
}
.searchRow > input:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.focusOutline:focus-visible,
.focusOutlineWithin:has(> :focus-visible) {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: var(--v4-size-focus-ring);
}
.focusOutlineInset:focus-visible {
  outline: var(--v4-size-focus-ring) solid var(--v4-ink);
  outline-offset: calc(-1 * var(--v4-size-focus-ring));
}
.selectTrigger {
  width: 100%;
  min-width: 0;
}
.selectTrigger [data-slot="select-value"] {
  display: block;
  min-width: 0;
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.group[data-variant="toolbar"] {
  gap: var(--v4-space-4);
}
.group[data-variant="spaced"] {
  gap: var(--v4-space-8);
  flex-wrap: wrap;
}
.group[data-variant="toolbar"] > *,
.group[data-variant="spaced"] > * {
  border-radius: calc(var(--v4-radius-control) * var(--corners));
}
.group[data-variant="toolbar"] > [data-slot="button"],
.group[data-variant="spaced"] > [data-slot="button"] {
  border-width: 1px;
}
:where(.card) {
  --v4-card-inset: var(--v4-space-surface-inset);
  --v4-card-body-inset: var(--v4-card-inset);
  --v4-card-lead: 0px;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  padding: 0;
  background: var(--v4-pop);
  border: var(--v4-size-control-border) solid var(--v4-line);
  border-radius: calc(var(--v4-radius-card) * var(--corners));
  box-shadow: none;
  font-family: var(--v4-type-body-font-family);
  font-size: var(--v4-type-body-font-size);
  line-height: var(--v4-type-body-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-body-letter-spacing);
  container-type: inline-size;
}
.card[data-size="sm"] {
  --v4-card-inset: var(--v4-space-surface-inset-sm);
}
.card:has(> .cardHeader [data-slot="media"]) {
  --v4-card-lead: calc(var(--v4-size-control-lg) + var(--v4-space-12));
}
.card:has(> .cardHeader [data-slot="media"][data-size="sm"]) {
  --v4-card-lead: calc(var(--v4-size-icon) + var(--v4-space-12));
}
:where(.cardHeader) {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
  gap: var(--v4-space-4) var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-card-inset);
}
:where(.cardHeading) {
  min-width: 0;
  overflow-wrap: anywhere;
  font-family: var(--v4-type-title-sm-font-family);
  font-size: var(--v4-type-title-sm-font-size);
  line-height: var(--v4-type-title-sm-line-height);
  font-weight: var(--v4-type-title-sm-font-weight);
  letter-spacing: var(--v4-type-title-sm-letter-spacing);
}
:where(.cardBody) {
  min-width: 0;
  padding: var(--v4-card-body-inset);
  padding-inline-start: calc(var(--v4-card-body-inset) + var(--v4-card-lead));
}
.cardHeader + .cardBody {
  padding-top: 0;
}
.cardPlain {
  background: var(--v4-surface);
}
.card[data-variant="framed"] > .cardHeader .cardTitleGroup {
  flex: 1;
  align-items: center;
}
.card[data-variant="framed"] > .cardHeader + .cardBody {
  padding-top: var(--v4-card-body-inset);
}
.card[data-variant="framed"] > .cardBody:has(+ .cardFooter) {
  border-bottom: 0;
  border-end-start-radius: 0;
  border-end-end-radius: 0;
  box-shadow: none;
}
.card[data-variant="framed"] > .cardBody + .cardFooter {
  border-top-color: var(--v4-line-soft);
  border-start-start-radius: 0;
  border-start-end-radius: 0;
}
.card[data-variant="framed"][data-flush] > .cardHeader {
  border-bottom: 0;
}
.card[data-variant="framed"][data-flush] > .cardBody {
  padding: 0;
  overflow: hidden;
}
.cardMedia {
  flex: 0 0 auto;
  display: inline-flex;
}
.cardTitleGroup {
  display: flex;
  align-items: flex-start;
  gap: var(--v4-space-12);
  min-width: 0;
  grid-column: 1;
  grid-row: 1 / span 2;
}
.cardCopy {
  flex: 1;
  min-width: 0;
}
.cardHeader > [data-slot="card-title"],
.cardHeader > [data-slot="card-description"] {
  grid-column: 1;
}
.cardDescription {
  color: var(--v4-text2);
  margin-top: var(--v4-space-4);
  overflow-wrap: anywhere;
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
}
.cardHeader > [data-slot="card-description"] {
  margin-top: 0;
}
:where(.cardAction) {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  max-width: 100%;
  height: var(--v4-type-title-sm-line-height);
  margin-inline-start: auto;
  grid-column: 2;
  grid-row: 1;
}
:where(.cardFooter) {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--v4-space-12);
  min-width: 0;
  padding: var(--v4-space-12) var(--v4-card-inset);
  padding-inline-start: calc(var(--v4-card-inset) + var(--v4-card-lead));
  border-top: var(--v4-size-control-border) solid var(--v4-line);
  color: var(--v4-text2);
  overflow-wrap: anywhere;
}
.choice {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  cursor: pointer;
}
.choiceText {
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.choiceTitle {
  font-family: var(--v4-type-field-label-font-family);
  font-size: var(--v4-type-field-label-font-size);
  line-height: var(--v4-type-field-label-line-height);
  font-weight: var(--v4-type-body-font-weight);
  letter-spacing: var(--v4-type-field-label-letter-spacing);
  color: var(--v4-ink);
}
.choiceDescription {
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
  font-weight: var(--v4-type-small-font-weight);
  letter-spacing: var(--v4-type-small-letter-spacing);
  color: var(--v4-muted);
}
.choiceRow {
  align-items: center;
  justify-content: space-between;
  padding-block: 12px;
  border-bottom: 1px solid var(--v4-line-soft);
}
.switch {
  --v4-switch-travel: 16px;
  box-sizing: border-box;
